"use strict";(self.webpackChunkmu_blog=self.webpackChunkmu_blog||[]).push([[749],{1895(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"2023/02/04/qv2ray-install","metadata":{"permalink":"/blog/2023/02/04/qv2ray-install","source":"@site/blog/2023-02-04-qv2ray-install.md","title":"\u5728 Ubuntu \u5b89\u88c5 Qv2ray","description":"\u5728 Ubuntu \u4e2d\u5b89\u88c5 Qv2ray\uff0c\u914d\u7f6e v2ray-core\uff0c\u5e76\u521b\u5efa\u4fbf\u4e8e\u542f\u52a8\u7684\u684c\u9762\u5165\u53e3\u3002","date":"2023-02-04T02:00:00.000Z","tags":[{"inline":false,"label":"Ubuntu","permalink":"/blog/tags/ubuntu"}],"readingTime":0.64,"hasTruncateMarker":true,"authors":[{"name":"GnehSizum","title":"Robotics Engineer","url":"https://github.com/GnehSizum","imageURL":"/images/head.jpg","key":"gnehsizum","page":null}],"frontMatter":{"title":"\u5728 Ubuntu \u5b89\u88c5 Qv2ray","description":"\u5728 Ubuntu \u4e2d\u5b89\u88c5 Qv2ray\uff0c\u914d\u7f6e v2ray-core\uff0c\u5e76\u521b\u5efa\u4fbf\u4e8e\u542f\u52a8\u7684\u684c\u9762\u5165\u53e3\u3002","date":"2023-02-04T02:00:00.000Z","authors":["gnehsizum"],"tags":["Ubuntu"],"slug":"2023/02/04/qv2ray-install"},"unlisted":false,"nextItem":{"title":"\u8054\u60f3\u5c0f\u65b0 Pro 14 \u5728 Ubuntu \u4e2d\u952e\u76d8\u5931\u6548\u7684\u95ee\u9898\u4fee\u590d","permalink":"/blog/2023/01/09/legion-keyboard"}},"content":"## 1. \u4e0b\u8f7d Qv2ray.AppImage\\n\\n\u4e0b\u8f7d\u5730\u5740\uff1a[https://github.com/Qv2ray/Qv2ray/releases/tag/v2.7.0](https://github.com/Qv2ray/Qv2ray/releases/tag/v2.7.0)\\n\\n\x3c!-- truncate --\x3e\\n\\n## 2. \u4e0b\u8f7d v2ray-core\\n\\n\u4e0b\u8f7d\u5730\u5740\uff1a[https://github.com/v2fly/v2ray-core/releases](https://github.com/v2fly/v2ray-core/releases)\\n\\n\u4e0b\u8f7d v4.45.2 \u7248\u672c\u5e76\u89e3\u538b\u3002\\n\\n## 3. \u914d\u7f6e Qv2ray\\n\\n- \u7ed9 Qv2ray.AppImage \u6dfb\u52a0\u6267\u884c\u6743\u9650\\n- \u6253\u5f00 Qv2ray.AppImage - \u9996\u9009\u9879 - \u5185\u6838\u8bbe\u7f6e\\n- \u201cV2Ray\u6838\u5fc3\u53ef\u6267\u884c\u6587\u4ef6\u8def\u5f84\u201d\u586b\u5199\u521a\u521a\u89e3\u538b\u7684\u76ee\u5f55\u4e2d v2ray \u7684\u8def\u5f84\\n- \u201cV2Ray\u8d44\u6e90\u76ee\u5f55\u201d\u586b\u5199\u521a\u521a\u89e3\u538b\u7684\u76ee\u5f55\u7684\u8def\u5f84\\n- \u70b9\u51fb\u201c\u68c0\u67e5V2Ray\u6838\u5fc3\u8bbe\u7f6e\u201d\uff0c\u914d\u7f6e\u68c0\u67e5\u901a\u8fc7\u5373\u53ef\u4f7f\u7528\u4e86\\n\\n## 4. \u6216\u8bb8\u4f60\u60f3\\n\\n\u6839\u636e [\u201c\u5173\u4e8e\u6211\u60f3\u5728\u4fa7\u8fb9\u680f\u6253\u5f00AppImage\u8fd9\u4ef6\u4e8b\u201d](/blog/2022/12/12/appimage-desktop/) \u521b\u5efa Desktop \u6587\u4ef6\u540e\u6253\u5f00\u5c31\u65b9\u4fbf\u591a\u4e86\u3002"},{"id":"2023/01/09/legion-keyboard","metadata":{"permalink":"/blog/2023/01/09/legion-keyboard","source":"@site/blog/2023-01-09-legion-keyboard.md","title":"\u8054\u60f3\u5c0f\u65b0 Pro 14 \u5728 Ubuntu \u4e2d\u952e\u76d8\u5931\u6548\u7684\u95ee\u9898\u4fee\u590d","description":"\u8054\u60f3\u5c0f\u65b0 Pro 14 \u5728 Ubuntu \u4e0b\u7684\u952e\u76d8\u6545\u969c\u8bb0\u5f55\uff1a\u5c1d\u8bd5\u66f4\u65b0\u5185\u6838\uff0c\u6700\u7ec8\u901a\u8fc7\u8c03\u6574 GRUB \u53c2\u6570\u89e3\u51b3\u3002","date":"2023-01-09T02:00:00.000Z","tags":[{"inline":false,"label":"Ubuntu","permalink":"/blog/tags/ubuntu"}],"readingTime":1,"hasTruncateMarker":true,"authors":[{"name":"GnehSizum","title":"Robotics Engineer","url":"https://github.com/GnehSizum","imageURL":"/images/head.jpg","key":"gnehsizum","page":null}],"frontMatter":{"title":"\u8054\u60f3\u5c0f\u65b0 Pro 14 \u5728 Ubuntu \u4e2d\u952e\u76d8\u5931\u6548\u7684\u95ee\u9898\u4fee\u590d","description":"\u8054\u60f3\u5c0f\u65b0 Pro 14 \u5728 Ubuntu \u4e0b\u7684\u952e\u76d8\u6545\u969c\u8bb0\u5f55\uff1a\u5c1d\u8bd5\u66f4\u65b0\u5185\u6838\uff0c\u6700\u7ec8\u901a\u8fc7\u8c03\u6574 GRUB \u53c2\u6570\u89e3\u51b3\u3002","date":"2023-01-09T02:00:00.000Z","authors":["gnehsizum"],"tags":["Ubuntu"],"slug":"2023/01/09/legion-keyboard"},"unlisted":false,"prevItem":{"title":"\u5728 Ubuntu \u5b89\u88c5 Qv2ray","permalink":"/blog/2023/02/04/qv2ray-install"},"nextItem":{"title":"\u5173\u4e8e\u6211\u60f3\u5728\u4fa7\u8fb9\u680f\u6253\u5f00 AppImage \u8fd9\u4ef6\u4e8b","permalink":"/blog/2022/12/12/appimage-desktop"}},"content":"> \u7279\u522b\u9e23\u8c22 cyy \u5b66\u59d0\u4e0e mj \u5b66\u957f\u7684\u5e2e\u52a9\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n\u672c\u6587\u65b9\u6cd5\u53ef\u80fd\u540c\u6837\u9002\u7528\u4e8e yoga 14s\u3002\\n\\n## \u65b9\u6cd51\uff1a\u4e70\u4e2a\u952e\u76d8\u5916\u63a5\u4f7f\u7528\\n\\n\u5728\u5b9e\u9645\u89e3\u51b3\u8fd9\u4e2a\u95ee\u9898\u4e4b\u524d \u6211\u4e00\u76f4\u662f\u7528\u8fd9\u4e2a\u529e\u6cd5_(:\u0437\u300d\u2220)_\\n\\n## \u65b9\u6cd52\uff1a\u66f4\u65b0\u5185\u6838\\n\\n\u4e00\u822c\u60c5\u51b5\u4e0b\uff0c\u66f4\u65b0\u5185\u6838\u53ef\u89e3\u51b3\u5927\u90e8\u5206\u95ee\u9898\u3002\u5177\u4f53\u65b9\u6cd5\u53ef\u81ea\u884c\u4e0a\u7f51\u67e5\u627e\u6559\u7a0b\uff0c\u8fd9\u91cc\u7ed9\u51fa\u6211\u7684\uff1a\\n\\n\u68c0\u67e5\u5185\u6838\u7248\u672c\uff1a\\n\\n```bash\\nuname -rs\\n```\\n\\n\u4e0b\u8f7d ubuntu-mainline-kernel \u811a\u672c\uff1a\\n\\n```bash\\nwget https://raw.githubusercontent.com/pimlie/ubuntu-mainline-kernel.sh/master/ubuntu-mainline-kernel.sh\\n```\\n\\n\u5c06\u811a\u672c\u653e\u5728\u53ef\u6267\u884c\u8def\u5f84\u4e2d\uff1a\\n\\n```bash\\nsudo install ubuntu-mainline-kernel.sh /usr/local/bin/\\n```\\n\\n\u68c0\u67e5\u6700\u65b0\u7684\u53ef\u7528\u5185\u6838\u7248\u672c\uff1a\\n\\n```bash\\nubuntu-mainline-kernel.sh -c\\n```\\n\\n\u83b7\u5f97\u6700\u65b0\u7248\u672c\u5e76\u786e\u8ba4\u8fd9\u5c31\u662f\u4f60\u60f3\u8981\u5b89\u88c5\u5728\u7cfb\u7edf\u4e0a\u7684\u7248\u672c\u540e\uff0c\u8fd0\u884c\uff1a\\n\\n```bash\\nsudo ubuntu-mainline-kernel.sh -i\\n```\\n\\n\u6700\u540e\u91cd\u542f\u7cfb\u7edf\uff0c\u5e76\u68c0\u67e5\u5185\u6838\u7248\u672c\uff1a\\n\\n```bash\\nuname -rs\\n```\\n\\n## \u65b9\u6cd53\uff1a\u4fee\u6539 grub\\n\\n\u65b9\u6cd52\u5bf9\u6211\u65e0\u6548\uff0c\u6700\u7ec8\u901a\u8fc7\u65b9\u6cd53\u89e3\u51b3\u95ee\u9898\u3002\\n\\n```bash\\nsudo gedit /etc/default/grub\\n```\\n\\n\u5c06\u6587\u4ef6\u4e2d\u7684 `GRUB_CMDLINE_LINUX_DEFAULT=\\"quiet splash\\"` \u4fee\u6539\u4e3a `GRUB_CMDLINE_LINUX_DEFAULT=\\"quiet splash i8042.dumbkbd\\"` \u3002\\n\\n\u4fdd\u5b58\u5173\u95ed\u540e\uff1a\\n\\n```bash\\nsudo update-grub\\n```\\n\\n\u6700\u540e\u91cd\u542f\u7cfb\u7edf\uff0c\u952e\u76d8\u5c31\u53ef\u4ee5\u4f7f\u7528\u4e86\u3002"},{"id":"2022/12/12/appimage-desktop","metadata":{"permalink":"/blog/2022/12/12/appimage-desktop","source":"@site/blog/2022-12-12-appimage-desktop.md","title":"\u5173\u4e8e\u6211\u60f3\u5728\u4fa7\u8fb9\u680f\u6253\u5f00 AppImage \u8fd9\u4ef6\u4e8b","description":"\u4e3a AppImage \u914d\u7f6e\u6267\u884c\u6743\u9650\u548c Desktop \u6587\u4ef6\uff0c\u5c06\u5e94\u7528\u6dfb\u52a0\u5230 Ubuntu \u542f\u52a8\u5668\u3002","date":"2022-12-12T02:00:00.000Z","tags":[{"inline":false,"label":"Ubuntu","permalink":"/blog/tags/ubuntu"}],"readingTime":0.46,"hasTruncateMarker":true,"authors":[{"name":"GnehSizum","title":"Robotics Engineer","url":"https://github.com/GnehSizum","imageURL":"/images/head.jpg","key":"gnehsizum","page":null}],"frontMatter":{"title":"\u5173\u4e8e\u6211\u60f3\u5728\u4fa7\u8fb9\u680f\u6253\u5f00 AppImage \u8fd9\u4ef6\u4e8b","description":"\u4e3a AppImage \u914d\u7f6e\u6267\u884c\u6743\u9650\u548c Desktop \u6587\u4ef6\uff0c\u5c06\u5e94\u7528\u6dfb\u52a0\u5230 Ubuntu \u542f\u52a8\u5668\u3002","date":"2022-12-12T02:00:00.000Z","authors":["gnehsizum"],"tags":["Ubuntu"],"slug":"2022/12/12/appimage-desktop"},"unlisted":false,"prevItem":{"title":"\u8054\u60f3\u5c0f\u65b0 Pro 14 \u5728 Ubuntu \u4e2d\u952e\u76d8\u5931\u6548\u7684\u95ee\u9898\u4fee\u590d","permalink":"/blog/2023/01/09/legion-keyboard"},"nextItem":{"title":"Hello World","permalink":"/blog/1970/01/01/hello-world"}},"content":"\u5176\u5b9e\u5f88\u7b80\u5355\uff0c\u4e5f\u5199\u8fc7\u5f88\u591a\u904d\u4e86\uff0c\u4f46\u7a81\u7136\u5c31\u60f3\u653e\u5230\u8fd9\u91cc\u6765\u5145\u6570:D\\n\\n\x3c!-- truncate --\x3e\\n\\n\u4ee5 groot2 \u4e3a\u4f8b\u3002\\n\\n## 1. \u8d4b\u4e88 AppImage \u6267\u884c\u6743\u9650\\n\\n```bash\\nchmod +x groot2-x86_64.AppImage\\n```\\n\\n## 2. \u521b\u5efa Desktop \u6587\u4ef6\\n\\n```bash\\ncd /usr/share/applications\\nsudo gedit groot2.desktop\\n```\\n\\n\u5199\u5165\uff1a\\n\\n```\\n[Desktop Entry]\\nName=groot2\\nExec=/home/mumu/groot2-x86_64.AppImage\\nIcon=/home/mumu/Pictures/icon/groot2.png\\nType=Application\\nStartupNotify=true\\n```\\n\\nicon \u6ca1\u6709\u7684\u8bdd\u53ef\u4ee5\u4e0d\u586b\uff0c\u5220\u53bb\u8fd9\u4e00\u884c\u3002\\n\\n\u4fee\u6539\u6743\u9650\uff1a\\n\\n```bash\\nsudo chmod a+x groot2.desktop\\n```\\n\\n\u597d\u4e86\uff0c\u5b8c\u4e8b\u513f\u3002"},{"id":"1970/01/01/hello-world","metadata":{"permalink":"/blog/1970/01/01/hello-world","source":"@site/blog/1970-01-01-hello-world.md","title":"Hello World","description":"The first post: a quick introduction to writing, previewing, and building a blog with Hexo.","date":"1970-01-01T02:00:00.000Z","tags":[{"inline":false,"label":"Hexo","permalink":"/blog/tags/hexo"}],"readingTime":0.56,"hasTruncateMarker":true,"authors":[{"name":"GnehSizum","title":"Robotics Engineer","url":"https://github.com/GnehSizum","imageURL":"/images/head.jpg","key":"gnehsizum","page":null}],"frontMatter":{"title":"Hello World","description":"The first post: a quick introduction to writing, previewing, and building a blog with Hexo.","date":"1970-01-01T02:00:00.000Z","authors":["gnehsizum"],"tags":["Hexo"],"slug":"1970/01/01/hello-world"},"unlisted":false,"prevItem":{"title":"\u5173\u4e8e\u6211\u60f3\u5728\u4fa7\u8fb9\u680f\u6253\u5f00 AppImage \u8fd9\u4ef6\u4e8b","permalink":"/blog/2022/12/12/appimage-desktop"}},"content":"Welcome to [Hexo](https://hexo.io/)! This is your very first post. Check [documentation](https://hexo.io/docs/) for more info. If you get any problems when using Hexo, you can find the answer in [troubleshooting](https://hexo.io/docs/troubleshooting.html) or you can ask me on [GitHub](https://github.com/hexojs/hexo/issues).\\n\\n\x3c!-- truncate --\x3e\\n\\n## Quick Start\\n\\n### Create a new post\\n\\n``` bash\\n$ hexo new \\"My New Post\\"\\n```\\n\\nMore info: [Writing](https://hexo.io/docs/writing.html)\\n\\n### Run server\\n\\n``` bash\\n$ hexo server\\n```\\n\\nMore info: [Server](https://hexo.io/docs/server.html)\\n\\n### Generate static files\\n\\n``` bash\\n$ hexo generate\\n```\\n\\nMore info: [Generating](https://hexo.io/docs/generating.html)\\n\\n### Deploy to remote sites\\n\\n``` bash\\n$ hexo deploy\\n```\\n\\nMore info: [Deployment](https://hexo.io/docs/one-command-deployment.html)"}]}}')}}]);